export interface LogoSvgOptions {
  /** Fill colour. Default brand red. */
  color?: string;
  /** Square side in px. Default 256. */
  size?: number;
  /** Opaque background; omit for transparent. */
  background?: string;
  /** Inset on every side as a fraction of `size` (0 ≤ p < 0.5). Default 0. */
  padding?: number;
}

/** The mark as a standalone square SVG. */
export function logoSvg(opts: LogoSvgOptions = {}): string {
  assertOptions(opts);
  const size = bounded(
    "logo size",
    orDefault<unknown>(opts.size, 256),
    1,
    MAX_DIMENSION,
  );
  const padding = orDefault<unknown>(opts.padding, 0);
  if (
    typeof padding !== "number" ||
    !Number.isFinite(padding) ||
    padding < 0 ||
    padding >= 0.5
  ) {
    throw new VisError(
      `logo padding must be in [0, 0.5), got ${describeValue(padding)}`,
    );
  }
  const fill = toHex(
    parseRgba("color", orDefault<unknown>(opts.color, "#ef4444")),
  );
  const inner = size * (1 - 2 * padding);
  const fit = fitAspect(
    { width: LOGO.width, height: LOGO.height },
    { width: inner, height: inner },
  );
  const offset = size * padding;
  const children: string[] = [];
  if (opts.background !== undefined) {
    children.push(
      el("rect", {
        width: size,
        height: size,
        fill: toHex(parseRgba("background", opts.background)),
      }),
    );
  }
  children.push(
    el(
      "g",
      {
        transform: `translate(${fmt(offset + fit.dx)} ${fmt(offset + fit.dy)}) scale(${fmt(fit.scale)}) translate(${fmt(-LOGO.x)} ${fmt(-LOGO.y)})`,
      },
      el("path", { d: LOGO.path, fill }),
    ),
  );
  return svgDoc({ width: size, height: size }, ...children);
}
